const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = Math.min(W, H) * 0.08;
    var s = Math.min((W - 2 * m) / 4, (H - 2 * m) / 3);
    var gw = s * 4;
    var gh = s * 3;
    var x0 = (W - gw) / 2;
    var y0 = (H - gh) / 2;
    var cmds = [];
    var i, x, y;
    for (i = 0; i <= 4; i++) {
      x = x0 + i * s;
      cmds = cmds.concat(visualSdk.polyline([[x, y0], [x, y0 + gh]]));
    }
    for (i = 0; i <= 3; i++) {
      y = y0 + i * s;
      cmds = cmds.concat(visualSdk.polyline([[x0, y], [x0 + gw, y]]));
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-3x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'grid', commands: cmds }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'grid', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' }
        ]
      }
    };
  }
};
